describe('Skip Navigation Links Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should have skip navigation links as the first focusable element', () => {
        cy.get('a.skip-navigation') // Adjust the selector based on the actual implementation
            .first()
            .should('be.visible')
            .focus()
            .then(($link) => {
                expect($link).to.have.attr('href').and.not.be.empty;
                cy.focused().should('equal', $link[0]);
            });
    });

    it('should not allow other elements to be focused before skip navigation links', () => {
        cy.get('body').tab(); // Simulate tabbing through focusable elements
        cy.focused().should('have.class', 'skip-navigation'); // Ensure the first focusable element is the skip link
    });
});
